Object.assign(COPY.en,{agentShare:'Agent order share',agentShareSub:'Share of placed orders by agent',categoryPieSub:'Share of booked value · all menu categories',chartTotal:'Total'});
Object.assign(COPY.ar,{agentShare:'حصة الموظفين من الطلبات',agentShareSub:'نسبة الطلبات المسجلة لكل موظف',categoryPieSub:'حصة القيمة المسجلة · كل فئات المنيو',chartTotal:'الإجمالي'});
let lang;try{lang=localStorage.getItem('caizo-language')==='ar'?'ar':'en'}catch{lang='en'}
let page=['overview','agents','branches','menu'].includes(location.hash.slice(1))?location.hash.slice(1):'overview',period=7,branch='all',orderType='all',category='all';
const SAMPLE_START='2026-08-26',SAMPLE_END='2026-09-24';
let rangeStart='2026-09-18',rangeEnd=SAMPLE_END,preset='7';
const dateMs=value=>Date.parse(value+'T00:00:00Z');
function validRange(start,end){return /^\d{4}-\d{2}-\d{2}$/.test(start)&&/^\d{4}-\d{2}-\d{2}$/.test(end)&&Number.isFinite(dateMs(start))&&Number.isFinite(dateMs(end))&&new Date(dateMs(start)).toISOString().slice(0,10)===start&&new Date(dateMs(end)).toISOString().slice(0,10)===end&&start>=SAMPLE_START&&end<=SAMPLE_END&&start<=end}
function setRange(start,end,choice='custom'){if(!validRange(start,end))return false;rangeStart=start;rangeEnd=end;period=Math.round((dateMs(end)-dateMs(start))/86400000)+1;preset=choice;return true}
function setPreset(choice){if(choice==='custom'){preset=choice;return}const days=Number(choice);setRange(new Date(dateMs(SAMPLE_END)-(days-1)*86400000).toISOString().slice(0,10),SAMPLE_END,choice)}
const formatDate=value=>new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}).format(new Date(dateMs(value)));
const rangeLabel=()=>rangeStart===rangeEnd?formatDate(rangeStart):formatDate(rangeStart)+' – '+formatDate(rangeEnd);
const address=b=>lang==='ar'?b.addressAr:b.addressEn;
const mapLink=b=>'<a class="linkbutton map-link" href="'+b.maps+'" target="_blank" rel="noopener noreferrer">'+t('mapsLink')+' ↗</a>';
const t=k=>COPY[lang][k]??k,name=o=>o[lang],num=(n,d=0)=>new Intl.NumberFormat(lang==='ar'?'ar-EG':'en-GB',{maximumFractionDigits:d}).format(n),pct=n=>num(n,1)+(lang==='ar'?'٪':'%'),money=n=>num(n)+' '+t('egp'),ratio=(a,b)=>b?a/b*100:0;
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',agents:'<path d="M4 14v-3a8 8 0 0 1 16 0v3M4 11h3v7H4zm13 0h3v7h-3zM17 18v3h-5"/>',branches:'<path d="M3 10h18l-2-6H5zM5 10v11h14V10M9 21v-7h6v7"/>',menu:'<path d="M5 3v7h5V3M7.5 10v11M17 3v18M17 3c-4 3-4 8 0 8"/>',calls:'<path d="M5 3h4l2 5-3 2a15 15 0 0 0 6 6l2-3 5 2v4c-7 5-22-10-16-16z"/>',orders:'<rect x="5" y="5" width="14" height="16" rx="2"/><path d="M9 5V3h6v2M9 11h6M9 15h4"/>',sales:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="12" cy="12" r="3"/>',conversion:'<path d="m4 17 6-6 4 3 6-10M14 4h6v6"/>'};
const icon=k=>'<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">'+(icons[k]||icons.overview)+'</svg>';
let seed=1849;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296}
function makeDemo(){let calls=[],orders=[];for(let day=0;day<30;day++){let date=new Date(Date.UTC(2026,7,26+day)).toISOString().slice(0,10);let count=710+Math.floor(rand()*230)+(day%7===1?180:0);for(let c=0;c<count;c++){let b=Math.floor(Math.pow(rand(),1.35)*BRANCHES.length),a=Math.floor(rand()*8),hour=rand()<.48?18+Math.floor(rand()*5):11+Math.floor(rand()*13),answered=rand()>.05-(b===BRANCHES.length-1?-.04:0),id='C'+calls.length;let wait=Math.floor(rand()*35),duration=100+Math.floor(rand()*220)+a*8;let call={id,date,hour,branchId:BRANCHES[b].id,agentId:AGENTS[a].id,answered,waitSeconds:wait,handlingSeconds:answered?duration:0};calls.push(call);if(answered&&rand()<.84-a*.021){let lines=[],main=rand()<.6?0:(rand()<.7?1:Math.floor(rand()*10)),quantity=1+Math.floor(rand()*3);lines.push({itemId:MENU[main].id,quantity,unitPrice:MENU[main].price});if(rand()<.64){let k=10+Math.floor(rand()*6);lines.push({itemId:MENU[k].id,quantity:1,unitPrice:MENU[k].price})}if(rand()<.59){let k=16+Math.floor(rand()*8);lines.push({itemId:MENU[k].id,quantity:1+Math.floor(rand()*2),unitPrice:MENU[k].price})}let roll=rand();orders.push({id:'O'+orders.length,callId:id,date,hour,branchId:call.branchId,agentId:call.agentId,type:rand()<.73?'delivery':'pickup',status:roll<(b===BRANCHES.length-1?.12:.035)?'cancelled':roll>.94?'pending':'completed',corrected:rand()<.025+a*.004,lines,value:lines.reduce((s,x)=>s+x.quantity*x.unitPrice,0)})}}}return{calls,orders}}
const DEMO=makeDemo();
// Explicit synthetic offer events; a multi-item basket alone is never attribution.
const UPSELL_OFFER={id:'SHAWARMA_1_TO_2',originalPrice:90,bundlePrice:170,extraVariableCost:45};
for(const [i,order] of DEMO.orders.entries()){
 const line=order.lines[0],agentIndex=Number(order.agentId.slice(1))-1;
 const offered=line.itemId==='M01'&&line.quantity<=2&&((i*17+agentIndex*11)%100)<(82-agentIndex*5);
 const accepted=offered&&line.quantity===2;
 const originalValue=accepted?order.value-90:order.value;
 if(accepted){line.unitPrice=85;order.value=order.lines.reduce((v,l)=>v+l.quantity*l.unitPrice,0)}
 order.upsell={offered,accepted,offerId:offered?UPSELL_OFFER.id:null,originalValue,finalValue:order.value,extraRevenue:accepted?order.value-originalValue:0,extraVariableCost:accepted?45:0,extraUnits:accepted?1:0};
}
function upsellStats(orders){const offered=orders.filter(o=>o.upsell?.offered),accepted=offered.filter(o=>o.upsell.accepted),completed=accepted.filter(o=>o.status==='completed');return{offered:offered.length,accepted:accepted.length,rate:ratio(accepted.length,offered.length),completed:completed.length,units:completed.reduce((v,o)=>v+o.upsell.extraUnits,0),revenue:completed.reduce((v,o)=>v+o.upsell.extraRevenue,0),cost:completed.reduce((v,o)=>v+o.upsell.extraVariableCost,0),contribution:completed.reduce((v,o)=>v+o.upsell.extraRevenue-o.upsell.extraVariableCost,0)}}

// A future provider must return { calls, orders } with the schema documented in README.
const dataProvider={getData:()=>DEMO};
function selected(){let data=dataProvider.getData(),base=x=>x.date>=rangeStart&&x.date<=rangeEnd&&(branch==='all'||x.branchId===branch);return{calls:data.calls.filter(base),orders:data.orders.filter(x=>base(x)&&(orderType==='all'||x.type===orderType))}}
const sum=(a,k)=>a.reduce((s,x)=>s+x[k],0);
function stats(calls,orders){let answered=calls.filter(x=>x.answered),done=orders.filter(x=>x.status==='completed');return{calls:calls.length,answered:answered.length,missed:calls.length-answered.length,orders:orders.length,value:sum(orders,'value'),conversion:ratio(orders.length,answered.length),answerRate:ratio(answered.length,calls.length),aov:orders.length?sum(orders,'value')/orders.length:0,handling:answered.length?sum(answered,'handlingSeconds')/answered.length/60:0,service:ratio(answered.filter(x=>x.waitSeconds<=20).length,calls.length),accuracy:ratio(orders.filter(x=>!x.corrected).length,orders.length),completed:done.length,completedValue:sum(done,'value'),cancelled:orders.filter(x=>x.status==='cancelled').length,pending:orders.filter(x=>x.status==='pending').length}}
function grouped(entities,key,calls,orders){return entities.map(e=>({...e,...stats(calls.filter(x=>x[key]===e.id),orders.filter(x=>x[key]===e.id))})).sort((a,b)=>b.orders-a.orders)}
function itemStats(orders){return MENU.map(item=>{let lines=orders.flatMap(o=>o.lines.filter(l=>l.itemId===item.id));return{...item,units:sum(lines,'quantity'),value:lines.reduce((s,x)=>s+x.quantity*x.unitPrice,0),orderCount:orders.filter(o=>o.lines.some(l=>l.itemId===item.id)).length}}).sort((a,b)=>b.units-a.units)}
const kpi=(label,value,foot,ico='overview',featured=false)=>`<section class="card kpi ${featured?'featured':''}"><div class="label">${t(label)}${icon(ico)}</div><div class="metric ${String(value).endsWith(t('egp'))?'moneyMetric':''}">${value}</div><div class="foot">${t(foot)}</div></section>`;
const head=(title,sub,extra='')=>`<div class="cardhead"><div><h2>${t(title)}</h2>${sub?`<p>${t(sub)}</p>`:''}</div>${extra}</div>`;
const link=(key,dest)=>`<button class="linkbutton" data-page="${dest}">${t(key)} <span aria-hidden="true">${lang==='ar'?'←':'→'}</span></button>`;
function pieChart(parts,format=num){const total=parts.reduce((v,p)=>v+p.value,0),colors=['#315f48','#a4c955','#738baa','#dc9668','#8874a8','#559e9d','#c19e37','#a67179'];let offset=0;const stops=parts.map((p,i)=>{const start=offset;offset+=ratio(p.value,total);return colors[i%colors.length]+' '+start+'% '+offset+'%'}).join(',');return `<figure class="pie-figure"><div class="pie-visual" role="img" aria-label="${parts.map(p=>p.label+': '+pct(ratio(p.value,total))).join('; ')}" style="background:conic-gradient(${total?stops:'#e5e9e3 0% 100%'})"></div><figcaption><div class="pie-total"><span>${t('chartTotal')}</span><strong>${format(total)}</strong></div>${parts.map((p,i)=>`<div class="pie-legend-row"><i style="background:${colors[i%colors.length]}" aria-hidden="true"></i><span>${p.label}</span><strong>${pct(ratio(p.value,total))}</strong><small>${format(p.value)}</small></div>`).join('')}</figcaption></figure>`}

let revealObserver=null;
function setupMotion(){
 if(revealObserver)revealObserver.disconnect();
 const targets=document.querySelectorAll('.main .heading,.main .filterbar,.main .date-range,.main .card,.main .category-tabs,.main .location-card,.main .rank-row,.main .mix-row,.main .pie-legend-row,.main tbody tr,.upsell-section>.cardhead');
 if(typeof IntersectionObserver==='undefined'||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)return;
 revealObserver=new IntersectionObserver(entries=>{for(const entry of entries){entry.target.classList.toggle('is-visible',entry.isIntersecting)}},{threshold:0,rootMargin:'-16px 0px -16px 0px'});
 targets.forEach((el,i)=>{el.classList.add('scroll-reveal');el.style.setProperty('--reveal-delay',Math.min(i%4,3)*35+'ms');revealObserver.observe(el)});
}
if(window.matchMedia){const motionPreference=window.matchMedia('(prefers-reduced-motion: reduce)');motionPreference.addEventListener?.('change',()=>{document.querySelectorAll('.scroll-reveal').forEach(el=>el.classList.remove('scroll-reveal','is-visible'));setupMotion()})}
function ranks(list,key,unit='orders'){let max=Math.max(1,...list.map(x=>x[key]));return list.slice(0,5).map((x,i)=>`<div class="rank-row"><span class="rank-no">${num(i+1,0)}</span><div class="rank-name">${name(x)}<div class="track"><i style="width:${x[key]/max*100}%"></i></div></div><strong>${unit==='sales'?money(x[key]):num(x[key])}</strong></div>`).join('')}
function donut(parts,total,label){let colors=['#315f48','#b5d778','#d9e0ce','#de9b73'],offset=0,gradient=parts.map((x,i)=>{let start=offset;offset+=ratio(x[1],total);return `${colors[i]} ${start}% ${offset}%`}).join(',');return `<div class="donut-wrap"><div class="donut" style="background:conic-gradient(${total?gradient:'#e9eee2 0% 100%'})"><div class="donut-text"><strong>${num(total)}</strong><small>${t(label)}</small></div></div></div>${parts.map((x,i)=>`<div class="mix-row"><span class="dot" style="background:${colors[i]}"></span><span>${t(x[0])}</span><strong>${num(x[1])}</strong><span class="pct">${pct(ratio(x[1],total))}</span></div>`).join('')}`}
function trend(calls,orders){let hourly=period===1,keys=hourly?Array.from({length:13},(_,i)=>i+11):Array.from({length:period},(_,i)=>new Date(dateMs(rangeStart)+i*86400000).toISOString().slice(0,10));let bins=keys.map(key=>({key,calls:calls.filter(c=>(hourly?c.hour:c.date)===key).length,orders:orders.filter(o=>(hourly?o.hour:o.date)===key).length}));let max=Math.ceil(Math.max(1,...bins.map(x=>x.calls))/100)*100,peak=bins.reduce((a,b)=>b.calls>a.calls?b:a,bins[0]);let label=k=>hourly?num(k)+':'+num(0).padStart(2,lang==='ar'?'٠':'0'):new Intl.DateTimeFormat(lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(k));return `<section class="card">${head('trend',hourly?'hourly':'trendSub',`<div class="legend"><span><i class="dot"></i>${t('calls')}</span><span><i class="dot light"></i>${t('orders')}</span></div>`)}<div class="chart" role="img" aria-label="${t('trend')}"><div class="yaxis">${[max,max*.75,max*.5,max*.25,0].map(n=>`<span>${num(n)}</span>`).join('')}</div><div class="plot">${bins.map((x,i)=>`<div class="bar-group" title="${label(x.key)}: ${t('calls')} ${num(x.calls)} · ${t('orders')} ${num(x.orders)}"><i style="height:${x.calls/max*87}%"></i><i class="orders" style="height:${x.orders/max*87}%"></i>${(period<10||i%5===0||i===bins.length-1)&&(!hourly||i%2===0)?`<span class="tick">${label(x.key)}</span>`:''}</div>`).join('')}</div></div><div class="chart-caption"><span>${t('daily')}: <b>${num(calls.length/period)}</b> ${t('calls')}</span><span>${t('peak')}: <b>${label(peak.key)}</b></span></div></section>`}
function ownerView(calls,orders,s){let bs=grouped(BRANCHES,'branchId',calls,orders),best=itemStats(orders)[0];return `<div class="kpis">${kpi('calls',num(s.calls),'callFoot','calls')}${kpi('orders',num(s.orders),'orderFoot','orders',true)}${kpi('sales',money(s.value),'salesFoot','sales')}${kpi('conversion',pct(s.conversion),'conversionFoot','conversion')}</div><div class="grid">${trend(calls,orders)}<section class="card">${head('orderMix','orderMixSub')}${donut([['delivery',orders.filter(x=>x.type==='delivery').length],['pickup',orders.filter(x=>x.type==='pickup').length]],orders.length,'orders')}</section></div><div class="grid"><section class="card">${head('topBranches','byOrders',link('viewBranches','branches'))}${ranks(bs,'orders')}</section><section class="card insight"><div class="eyebrow">${t('insight')}</div><h2>${t('missedTitle')}</h2><div class="highlight">${num(s.missed)}</div><p>${t('missedText')}</p>${link('viewAgents','agents')}</section></div><div class="grid equal"><section class="card">${head('bestSeller','',link('viewMenu','menu'))}<div class="menu-champion"><div><h2>${name(best)}</h2><p>${t(best.category)}</p><div class="compact-metrics"><div class="small muted">${t('units')}<strong>${num(best.units)}</strong></div><div class="small muted">${t('itemValue')}<strong>${money(best.value)}</strong></div></div></div><span class="big-index">${num(1).padStart(2,lang==='ar'?'٠':'0')}</span></div></section><section class="card">${head('outcomes','outcomesSub')}${[['orders',s.orders],['other',s.answered-s.orders],['missed',s.missed]].map((x,i)=>`<div class="mix-row"><span class="dot" style="background:${['#315f48','#b5d778','#de9b73'][i]}"></span>${t(x[0])}<strong>${num(x[1])}</strong><span class="pct">${pct(ratio(x[1],s.calls))}</span></div>`).join('')}<p class="note">${t('filterNote')}</p></section></div>`}

function upsellCards(orders){const u=upsellStats(orders);return '<div class="kpis">'+kpi('upsellAccepted',num(u.accepted),'upsellAcceptedFoot','orders')+kpi('upsellRate',pct(u.rate),'upsellRateFoot','conversion')+kpi('upsellRevenue',money(u.revenue),'upsellCompletedFoot','sales',true)+kpi('upsellProfit',money(u.contribution),'upsellProfitFoot','sales')+'</div>'}
function upsellSection(orders){const rows=AGENTS.map(a=>({...a,...upsellStats(orders.filter(o=>o.agentId===a.id))})).sort((a,b)=>b.revenue-a.revenue),recent=orders.filter(o=>o.status==='completed'&&o.upsell.accepted).slice(-5).reverse();return `<section class="upsell-section"><div class="cardhead"><div><div class="eyebrow">${t('orderTarget')}</div><h2>${t('upsell')}</h2><p>${t('upsellSub')}</p></div></div>${upsellCards(orders)}<section class="card upsell-example">${head('upsellExample','')}<div class="upsell-flow"><div><span>${t('upsellBefore')}</span><h3>${t('upsellOne')}</h3><strong>${money(90)}</strong></div><b aria-hidden="true">${lang==='ar'?'←':'→'}</b><div><span>${t('upsellAfter')}</span><h3>${t('upsellTwo')}</h3><strong>${money(170)}</strong></div><div class="upsell-gain"><span>${t('upsellRevenue')}</span><strong>+${money(80)}</strong><small>${t('upsellProfit')}: ${money(35)}</small></div></div><p class="note">${t('upsellAssumption')}</p></section><section class="card section-gap">${head('upsellRanking','upsellRankSub')}<div class="table-wrap"><table><thead><tr>${['agent','upsellOffers','upsellAccepted','upsellRate','upsellCompleted','upsellUnits','upsellRevenue','upsellProfit'].map(k=>'<th scope="col">'+t(k)+'</th>').join('')}</tr></thead><tbody>${rows.map(a=>`<tr><td><button class="namebtn" data-detail="agent:${a.id}">${name(a)}</button></td><td>${num(a.offered)}</td><td>${num(a.accepted)}</td><td>${pct(a.rate)}</td><td>${num(a.completed)}</td><td>${num(a.units)}</td><td><b>${money(a.revenue)}</b></td><td>${money(a.contribution)}</td></tr>`).join('')}</tbody></table></div><p class="note">${t('upsellAttribution')} ${t('upsellCompletedFoot')}</p></section><section class="card section-gap">${head('upsellProof','upsellProofSub')}<div class="table-wrap"><table><thead><tr>${['upsellOrder','upsellDate','agent','upsellOriginal','upsellFinal','upsellRevenue','upsellProfit'].map(k=>'<th scope="col">'+t(k)+'</th>').join('')}</tr></thead><tbody>${recent.map(o=>`<tr><td>${num(Number(o.id.slice(1))+1)}</td><td>${formatDate(o.date)}</td><td>${name(AGENTS.find(a=>a.id===o.agentId))}</td><td>${money(o.upsell.originalValue)}</td><td>${money(o.upsell.finalValue)}</td><td>+${money(o.upsell.extraRevenue)}</td><td>${money(o.upsell.extraRevenue-o.upsell.extraVariableCost)}</td></tr>`).join('')||'<tr><td colspan="7">'+t('upsellNoRows')+'</td></tr>'}</tbody></table></div><p class="note">${t('upsellAssumption')}</p></section></section>`}

function agentView(calls,orders,s){let rows=grouped(AGENTS,'agentId',calls,orders),low=[...rows].filter(x=>x.answered).sort((a,b)=>a.conversion-b.conversion)[0];return `<div class="kpis">${kpi('answered',num(s.answered),'teamSize','calls')}${kpi('conversion',pct(s.conversion),'conversionFoot','conversion',true)}${kpi('handling',num(s.handling,1)+' '+t('mins'),'channelNote','agents')}${kpi('quality',pct(s.accuracy),'accuracyFoot','orders')}</div>${upsellSection(orders)}<div class="grid"><section class="card">${head('agentShare','agentShareSub')}${pieChart(rows.map(a=>({label:name(a),value:a.orders})))}</section><section class="card insight"><div class="eyebrow">${t('coaching')}</div><h2>${low?name(low):t('noData')}</h2><div class="highlight">${pct(low?.conversion||0)}</div><p>${t('coachingText')}</p></section></div><section class="card">${head('team','teamSub')}<div class="table-wrap"><table><thead><tr>${['agent','calls','answered','orders','conversion','handling','quality','sales'].map(k=>`<th scope="col">${t(k)}</th>`).join('')}</tr></thead><tbody>${rows.map((x,i)=>`<tr><td><button class="namebtn" data-detail="agent:${x.id}"><span class="initial">${num(i+1)}</span>${name(x)}</button></td><td>${num(x.calls)}</td><td>${num(x.answered)}</td><td><b>${num(x.orders)}</b></td><td><span class="status ${x.conversion<73?'warn':''}">${pct(x.conversion)}</span></td><td>${num(x.handling,1)} ${t('mins')}</td><td>${pct(x.accuracy)}</td><td>${money(x.value)}</td></tr>`).join('')}</tbody></table></div><p class="note">${t('filterNote')}</p></section>`}
function branchView(calls,orders,s){let rows=grouped(BRANCHES.filter(b=>branch==='all'||b.id===branch),'branchId',calls,orders),worst=[...rows].filter(x=>x.orders).sort((a,b)=>b.cancelled/b.orders-a.cancelled/a.orders)[0];return `<div class="kpis">${kpi('orders',num(s.orders),'orderFoot','orders')}${kpi('completedValue',money(s.completedValue),'completedFoot','sales',true)}${kpi('aov',money(s.aov),'salesFoot','sales')}${kpi('cancelRate',pct(ratio(s.cancelled,s.orders)),'cancelFoot','branches')}</div><div class="grid"><section class="card">${head('fulfillment','statusNote')}${donut([['completed',s.completed],['pending',s.pending],['cancelled',s.cancelled]],s.orders,'orders')}</section><section class="card insight"><div class="eyebrow">${t('branchInsight')}</div><h2>${worst?name(worst):t('noData')}</h2><div class="highlight">${pct(worst?ratio(worst.cancelled,worst.orders):0)}</div><p>${t('branchInsightText')}</p><p class="note">${t('branchAssumption')}</p></section></div><section class="card">${head('network','networkSub')}<div class="table-wrap"><table><thead><tr>${['branch','orders','sales','aov','completed','cancelled','completion'].map(k=>`<th scope="col">${t(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td><button class="namebtn" data-detail="branch:${x.id}">${name(x)}</button></td><td><b>${num(x.orders)}</b></td><td>${money(x.value)}</td><td>${money(x.aov)}</td><td>${num(x.completed)}</td><td>${num(x.cancelled)}</td><td><span class="status ${ratio(x.completed,x.orders)<88?'warn':''}">${pct(ratio(x.completed,x.orders))}</span></td></tr>`).join('')}</tbody></table></div><p class="note">${t('branchAssumption')}</p></section><section class="card section-gap">${head('locations','locationsSub')}<div class="location-grid">${BRANCHES.filter(b=>branch==='all'||b.id===branch).map(b=>`<article class="location-card"><h3>${name(b)}</h3><p>${address(b)}</p>${mapLink(b)}</article>`).join('')}</div><p class="note">${t('mapsChecked')}</p></section>`}
function menuView(calls,orders,s){let all=itemStats(orders),rows=all.filter(x=>category==='all'||x.category===category),units=sum(rows,'units'),value=sum(rows,'value'),best=rows[0],cats=['shawarma','hawawshi','sides','drinks'].map(k=>({en:COPY.en[k],ar:COPY.ar[k],value:sum(all.filter(x=>x.category===k),'value')})).sort((a,b)=>b.value-a.value);return `<div class="kpis">${kpi('totalUnits',num(units),'channelNote','menu')}${kpi('itemValue',money(value),'salesFoot','sales',true)}${kpi('itemsCount',num(rows.filter(x=>x.units).length),'menuCoverage','menu')}${kpi('aov',money(s.aov),'orderFoot','orders')}</div><div class="grid"><section class="card">${head('bestSeller','')}<div class="menu-champion"><div><div class="eyebrow">${t(best.category)}</div><h2>${name(best)}</h2><p>${t('price')}: ${money(best.price)}</p><div class="compact-metrics"><div class="small muted">${t('units')}<strong>${num(best.units)}</strong></div><div class="small muted">${t('itemValue')}<strong>${money(best.value)}</strong></div></div></div><span class="big-index">${num(1).padStart(2,lang==='ar'?'٠':'0')}</span></div><p class="note">${t('menuNote')}</p></section><section class="card">${head('categoryMix','categoryPieSub')}${pieChart(cats.map(c=>({label:name(c),value:c.value})),money)}</section></div><div class="category-tabs" aria-label="${t('category')}">${['all','shawarma','hawawshi','sides','drinks'].map(k=>`<button data-category="${k}" class="${category===k?'active':''}" aria-pressed="${category===k}">${t(k==='all'?'allCategories':k)}</button>`).join('')}</div><section class="card">${head('menuTable','menuTableSub')}<div class="table-wrap"><table><thead><tr>${['item','category','price','units','itemValue','share'].map(k=>`<th scope="col">${t(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(x=>`<tr><td><button class="namebtn" data-detail="item:${x.id}">${name(x)}</button></td><td class="muted">${t(x.category)}</td><td>${money(x.price)}</td><td><b>${num(x.units)}</b></td><td>${money(x.value)}</td><td>${pct(ratio(x.value,s.value))}</td></tr>`).join('')}</tbody></table></div><p class="note">${t('menuNote')}</p></section>`}
function render(){document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';document.title=(lang==='ar'?'كايزو × زيليفِيت | ':'Caizo × Xelevate | ')+t(page);let{calls,orders}=selected(),s=stats(calls,orders);document.getElementById('app').innerHTML=`<aside class="sidebar"><div class="brand"><img src="logo.webp" width="1600" height="414" alt="${lang==='ar'?'كايزو':'Caizo'}"></div><div class="workspace">${t('studio')}<br>${t('channelNote')}</div><div class="navlabel">${t('navigation')}</div><nav class="nav" aria-label="${t('navigation')}">${['overview','agents','branches','menu'].map(k=>`<button data-page="${k}" class="${page===k?'active':''}" ${page===k?'aria-current="page"':''}>${icon(k)}${t(k)}</button>`).join('')}</nav><div class="side-bottom"><small>${t('powered')}</small><div class="xelevate">${lang==='ar'?'زيليفِيت':'XELEVATE'}</div><p class="side-note">${t('sideNote')}</p></div></aside><main class="main"><header class="topbar"><div class="crumb"><span class="muted">${lang==='ar'?'كايزو':'Caizo'}</span><span class="muted">/</span><span>${t(page)}</span></div><div class="top-actions"><span class="pill">${t('demo')}</span><div class="languages" aria-label="Language / اللغة"><button data-lang="en" class="${lang==='en'?'selected':''}" aria-pressed="${lang==='en'}">EN</button><button data-lang="ar" class="${lang==='ar'?'selected':''}" aria-pressed="${lang==='ar'}">AR</button></div><div class="avatar" title="${t('owner')}">${lang==='ar'?'م':'O'}</div></div></header><div class="content"><div class="heading"><div><div class="eyebrow">${t('workspace')}</div><h1>${t(page==='overview'?'hello':page)}</h1><p>${t(page+'Sub')}</p></div><span class="date-tag">${rangeLabel()}</span></div><div class="filterbar"><label for="period">${t('period')}<select id="period">${[['1','today'],['7','week'],['30','month'],['custom','custom']].map(x=>`<option value="${x[0]}" ${preset===x[0]?'selected':''}>${t(x[1])}</option>`).join('')}</select></label><label for="branch">${t('branch')}<select id="branch"><option value="all">${t('allBranches')}</option>${BRANCHES.map(x=>`<option value="${x.id}" ${branch===x.id?'selected':''}>${name(x)}</option>`).join('')}</select></label><label for="type" class="last">${t('type')}<select id="type">${['all','delivery','pickup'].map(x=>`<option value="${x}" ${orderType===x?'selected':''}>${t(x==='all'?'allTypes':x)}</option>`).join('')}</select></label></div><form id="date-range" class="date-range"><div class="range-inputs"><label for="date-from">${t('from')}<input id="date-from" type="date" min="${SAMPLE_START}" max="${SAMPLE_END}" value="${rangeStart}" required></label><span class="range-dash" aria-hidden="true">—</span><label for="date-to">${t('to')}<input id="date-to" type="date" min="${SAMPLE_START}" max="${SAMPLE_END}" value="${rangeEnd}" required></label><button class="apply-range" type="submit">${t('applyRange')}</button></div><p class="note">${t('dateHelp')}</p><p id="date-error" class="date-error" role="alert"></p></form><div id="view">${({overview:ownerView,agents:agentView,branches:branchView,menu:menuView}[page])(calls,orders,s)}</div><footer class="footer"><span>${t('foot')}</span><button class="linkbutton" data-about>${t('dataInfo')} ⓘ</button></footer></div></main>`;document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>{page=el.dataset.page;location.hash=page;render();window.scrollTo(0,0)});document.querySelectorAll('[data-lang]').forEach(el=>el.onclick=()=>{lang=el.dataset.lang;try{localStorage.setItem('caizo-language',lang)}catch{}render()});document.getElementById('period').onchange=e=>{setPreset(e.target.value);render();if(preset==='custom')document.getElementById('date-from').focus()};document.getElementById('date-range').onsubmit=e=>{e.preventDefault();const start=document.getElementById('date-from').value,end=document.getElementById('date-to').value;if(!setRange(start,end)){document.getElementById('date-error').textContent=t('dateInvalid');return}render()};document.getElementById('branch').onchange=e=>{branch=e.target.value;render()};document.getElementById('type').onchange=e=>{orderType=e.target.value;render()};document.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{category=el.dataset.category;render()});document.querySelectorAll('[data-detail]').forEach(el=>el.onclick=()=>detail(el.dataset.detail));document.querySelector('[data-about]').onclick=about;setupMotion();}
function showDialog(title,body){let dialog=document.getElementById('detail');dialog.innerHTML=`<div class="cardhead"><h2 id="dialog-title">${title}</h2><button class="close">${t('close')} ×</button></div>${body}`;dialog.setAttribute('aria-labelledby','dialog-title');dialog.querySelector('.close').onclick=()=>dialog.close();dialog.showModal()}
function detail(key){let[k,id]=key.split(':'),{calls,orders}=selected();if(k==='item'){let item=MENU.find(x=>x.id===id),os=orders.filter(o=>o.lines.some(x=>x.itemId===id)),v=itemStats(os).find(x=>x.id===id);showDialog(name(item),`<p>${t(item.category)} · ${t('price')}: ${money(item.price)}</p><div class="kpis">${kpi('units',num(v.units),'channelNote','menu',true)}${kpi('itemValue',money(v.value),'salesFoot','sales')}${kpi('orderCount',num(os.length),'orderFoot','orders')}</div><p>${t('menuNote')}</p>`);return}let entities=k==='agent'?AGENTS:BRANCHES,field=k==='agent'?'agentId':'branchId',entity=entities.find(x=>x.id===id),cs=calls.filter(x=>x[field]===id),os=orders.filter(x=>x[field]===id),s=stats(cs,os);showDialog(name(entity),`${k==='branch'?`<div class="branch-address"><p>${address(entity)}</p>${mapLink(entity)}<p class="note">${t('mapsChecked')}</p></div>`:''}<p>${t('details')} · ${rangeLabel()}</p><div class="kpis">${kpi('orders',num(s.orders),'orderFoot','orders',true)}${kpi('sales',money(s.value),'salesFoot','sales')}${k==='agent'?kpi('answerRate',pct(s.answerRate),'callFoot','calls')+kpi('service',pct(s.service),'callFoot','agents'):kpi('completedValue',money(s.completedValue),'completedFoot','sales')+kpi('cancelRate',pct(ratio(s.cancelled,s.orders)),'cancelFoot','branches')}</div>${k==='agent'?`<h3>${t('upsellSummary')}</h3>${upsellCards(os)}<p class="note">${t('upsellAssumption')}</p>`:''}${head('orderMix','')}${donut([['delivery',os.filter(x=>x.type==='delivery').length],['pickup',os.filter(x=>x.type==='pickup').length]],os.length,'orders')}<p>${t('filterNote')}</p>`)}
function about(){showDialog(t('dataInfo'),`<h3>${t('assumptions')}</h3><p>${t('assumptionsText')}</p><h3>${t('future')}</h3><p>${t('futureText')}</p><ol>${['step1','step2','step3','step4'].map(k=>`<li>${t(k)}</li>`).join('')}</ol><p><b>${t('important')}</b></p><h3>${t('definitions')}</h3><p>${t('definitionText')}</p><p>${t('netNote')}</p><h3>${t('sources')}</h3><p>${t('menuNote')} <a href="https://directory.ordegate.com/directory/page/caizo?lang=${lang}" target="_blank" rel="noopener noreferrer">${t('sourceLink')}</a></p>`)}
window.addEventListener('hashchange',()=>{let next=location.hash.slice(1);if(['overview','agents','branches','menu'].includes(next)&&next!==page){page=next;render()}});
render();


